// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.string.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.TupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.json.JsonSupport;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.SplitTupleFunction;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of the {@code strf:} functions other than {@code regexpExtract} (see {@link RegexpExtractEdgeCaseTest}).
 */
class StringFunctionsEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final String SMILEY = "😀"; // U+1F600, one code point, two UTF-16 units

	private static final String DECOMPOSED_E = "é"; // e + combining acute accent, two code points

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal en(String s) {
		return VF.createLiteral(s, "en");
	}

	private static Literal integer(int i) {
		return VF.createLiteral(i);
	}

	private static List<Value> jsonArrayValues(Literal array) {
		assertThat(array.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		List<?> parsed = (List<?>) JsonSupport.parse(array.getLabel());
		List<Value> values = new ArrayList<>(parsed.size());
		for (Object element : parsed) {
			values.add(JsonSupport.toValue(element, VF));
		}
		return values;
	}

	private static List<Value> rows(TupleFunction function, Value... args) {
		List<Value> values = new ArrayList<>();
		try (var rows = function.evaluate(VF, args)) {
			while (rows.hasNext()) {
				List<? extends Value> row = rows.next();
				assertThat(row).hasSize(1);
				values.add(row.get(0));
			}
		}
		return values;
	}

	// ---------------------------------------------------------------- family-wide string cases

	@Test
	void emptyStringInputIsHandledByEveryFunction() {
		assertThat(new Trim().evaluate(VF, str(""))).isEqualTo(str(""));
		assertThat(new LPad().evaluate(VF, str(""), integer(2))).isEqualTo(str("  "));
		assertThat(new Repeat().evaluate(VF, str(""), integer(3))).isEqualTo(str(""));
		assertThat(new Reverse().evaluate(VF, str(""))).isEqualTo(str(""));
		assertThat(new Left().evaluate(VF, str(""), integer(3))).isEqualTo(str(""));
		assertThat(new Right().evaluate(VF, str(""), integer(3))).isEqualTo(str(""));
		assertThat(new Position().evaluate(VF, str("a"), str("")).intValue()).isEqualTo(0);
		assertThat(new LastIndexOf().evaluate(VF, str(""), str("a")).intValue()).isEqualTo(0);
		assertThat(new SplitPart().evaluate(VF, str(""), str(","), integer(1))).isEqualTo(str(""));
		assertThat(new ConcatWs().evaluate(VF, str(","), str(""), str(""))).isEqualTo(str(","));
		assertThat(new Translate().evaluate(VF, str(""), str("a"), str("b"))).isEqualTo(str(""));
		assertThat(new InitCap().evaluate(VF, str(""))).isEqualTo(str(""));
		assertThat(new Normalize().evaluate(VF, str(""))).isEqualTo(str(""));
	}

	@Test
	void literalKindOfTheSourceIsPreserved() {
		Literal langString = en("  hi  ");
		Literal xsdString = VF.createLiteral("  hi  ", CoreDatatype.XSD.STRING);
		Literal rtl = VF.createLiteral("  hi  ", "ar", Literal.BaseDirection.RTL);
		assertThat(new Trim().evaluate(VF, langString)).isEqualTo(en("hi"));
		assertThat(new Trim().evaluate(VF, xsdString).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.STRING);
		assertThat(new Trim().evaluate(VF, rtl)).isEqualTo(VF.createLiteral("hi", "ar", Literal.BaseDirection.RTL));
		assertThat(new Reverse().evaluate(VF, en("ab"))).isEqualTo(en("ba"));
		assertThat(new Left().evaluate(VF, en("abc"), integer(1))).isEqualTo(en("a"));
		assertThat(new SplitPart().evaluate(VF, en("a,b"), str(","), integer(2))).isEqualTo(en("b"));
		assertThat(new Translate().evaluate(VF, en("abc"), str("a"), str("x"))).isEqualTo(en("xbc"));
		assertThat(new InitCap().evaluate(VF, en("abc"))).isEqualTo(en("Abc"));
	}

	@Test
	void astralCodePointsCountAsOneCharacter() {
		assertThat(new Position().evaluate(VF, str("b"), str(SMILEY + SMILEY + "b")).intValue()).isEqualTo(3);
		assertThat(new LastIndexOf().evaluate(VF, str(SMILEY + "b" + SMILEY + "b"), str("b")).intValue())
				.isEqualTo(4);
		assertThat(new Left().evaluate(VF, str(SMILEY + SMILEY + "x"), integer(1))).isEqualTo(str(SMILEY));
		assertThat(new Right().evaluate(VF, str("x" + SMILEY + SMILEY), integer(1))).isEqualTo(str(SMILEY));
		assertThat(new LPad().evaluate(VF, str(SMILEY), integer(2))).isEqualTo(str(" " + SMILEY));
		assertThat(new Ascii().evaluate(VF, str(SMILEY + "a")).intValue()).isEqualTo(0x1F600);
	}

	@Test
	void combiningCharactersAreNotNormalizedImplicitly() {
		assertThat(new Reverse().evaluate(VF, str(DECOMPOSED_E))).isEqualTo(str("́e"));
		assertThat(new Left().evaluate(VF, str(DECOMPOSED_E), integer(1))).isEqualTo(str("e"));
		assertThat(new LPad().evaluate(VF, str(DECOMPOSED_E), integer(3), str("-"))).isEqualTo(str("-" + DECOMPOSED_E));
		assertThat(new Position().evaluate(VF, str("́"), str(DECOMPOSED_E)).intValue()).isEqualTo(2);
		assertThat(new Position().evaluate(VF, str("é"), str(DECOMPOSED_E)).intValue()).isEqualTo(0);
	}

	@Test
	void nonStringLiteralIsAnEvaluationErrorNotCoerced() {
		// pins current behaviour: no string coercion of numeric literals
		assertThatThrownBy(() -> new Reverse().evaluate(VF, integer(12)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Left().evaluate(VF, VF.createLiteral(1.5), integer(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Repeat().evaluate(VF, VF.createLiteral(true), integer(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	// ---------------------------------------------------------------- trim, ltrim, rtrim

	@Test
	void trimRemovesJavaWhitespaceButNotNonBreakingOrZeroWidthSpaces() {
		// pins current behaviour: Character.isWhitespace semantics
		assertThat(new Trim().evaluate(VF, str("\t\n\r\u000B\f hi  　"))).isEqualTo(str("hi"));
		assertThat(new Trim().evaluate(VF, str(" hi "))).isEqualTo(str(" hi "));
		assertThat(new Trim().evaluate(VF, str(" hi "))).isEqualTo(str(" hi "));
		assertThat(new Trim().evaluate(VF, str("​hi​"))).isEqualTo(str("​hi​"));
		assertThat(new LTrim().evaluate(VF, str("  hi"))).isEqualTo(str("  hi"));
		assertThat(new RTrim().evaluate(VF, str("hi  "))).isEqualTo(str("hi  "));
	}

	@Test
	void trimCharsetIsLiteralNotARegex() {
		assertThat(new Trim().evaluate(VF, str("xxhixx"), str("x"))).isEqualTo(str("hi"));
		assertThat(new Trim().evaluate(VF, str("[]hi[]"), str("[]"))).isEqualTo(str("hi"));
		assertThat(new Trim().evaluate(VF, str(".*hi.*"), str(".*"))).isEqualTo(str("hi"));
		assertThat(new Trim().evaluate(VF, str("ahia"), str("."))).isEqualTo(str("ahia"));
		assertThat(new LTrim().evaluate(VF, str("[]hi[]"), str("[]"))).isEqualTo(str("hi[]"));
		assertThat(new RTrim().evaluate(VF, str("[]hi[]"), str("[]"))).isEqualTo(str("[]hi"));
	}

	@Test
	void trimCharsetWithAstralCharacters() {
		assertThat(new Trim().evaluate(VF, str(SMILEY + SMILEY + "hi" + SMILEY), str(SMILEY))).isEqualTo(str("hi"));
		assertThat(new LTrim().evaluate(VF, str(SMILEY + "hi" + SMILEY), str(SMILEY))).isEqualTo(str("hi" + SMILEY));
		assertThat(new RTrim().evaluate(VF, str(SMILEY + "hi" + SMILEY), str(SMILEY))).isEqualTo(str(SMILEY + "hi"));
		// the charset is matched by code point: the high surrogate alone is not in the charset
		assertThat(new Trim().evaluate(VF, str(SMILEY + "hi"), str("\uD83D"))).isEqualTo(str(SMILEY + "hi"));
	}

	@Test
	void trimOfOnlyTrimmableCharactersIsEmpty() {
		assertThat(new Trim().evaluate(VF, str("   \t"))).isEqualTo(str(""));
		assertThat(new Trim().evaluate(VF, str("xxx"), str("x"))).isEqualTo(str(""));
		assertThat(new LTrim().evaluate(VF, str("xyxy"), str("xy"))).isEqualTo(str(""));
		assertThat(new RTrim().evaluate(VF, en("xyxy"), str("xy"))).isEqualTo(en(""));
	}

	@Test
	void trimWithEmptyCharsetLeavesInputUnchanged() {
		// pins current behaviour: an empty charset trims nothing (it does not fall back to white space)
		Literal input = str("  hi  ");
		assertThat(new Trim().evaluate(VF, input, str(""))).isSameAs(input);
		assertThat(new LTrim().evaluate(VF, input, str(""))).isSameAs(input);
		assertThat(new RTrim().evaluate(VF, input, str(""))).isSameAs(input);
	}

	// ---------------------------------------------------------------- lpad, rpad

	@Test
	void padTruncatesKeepingThePrefixOnBothSides() {
		// pins current behaviour: PostgreSQL semantics, both lpad and rpad keep the first n code points
		assertThat(new LPad().evaluate(VF, str("a" + SMILEY + "b"), integer(2))).isEqualTo(str("a" + SMILEY));
		assertThat(new RPad().evaluate(VF, str("a" + SMILEY + "b"), integer(2))).isEqualTo(str("a" + SMILEY));
		assertThat(new RPad().evaluate(VF, str("hello"), integer(3), str("xy"))).isEqualTo(str("hel"));
	}

	@Test
	void padWithZeroOrNegativeWidthIsEmpty() {
		// pins current behaviour: negative widths behave like zero rather than raising an error
		assertThat(new RPad().evaluate(VF, str("hello"), integer(0))).isEqualTo(str(""));
		assertThat(new LPad().evaluate(VF, str("hello"), integer(-3))).isEqualTo(str(""));
		assertThat(new RPad().evaluate(VF, en("hello"), integer(-1))).isEqualTo(en(""));
	}

	@Test
	void multiCharacterFillWraps() {
		assertThat(new LPad().evaluate(VF, str("a"), integer(5), str("xy"))).isEqualTo(str("xyxya"));
		assertThat(new RPad().evaluate(VF, str("a"), integer(5), str("xy"))).isEqualTo(str("axyxy"));
		assertThat(new LPad().evaluate(VF, str("a"), integer(6), str("xy"))).isEqualTo(str("xyxyxa"));
	}

	@Test
	void emptyFillLeavesInputUnchanged() {
		// pins current behaviour: an empty fill string pads nothing instead of raising an error
		Literal input = str("a");
		assertThat(new LPad().evaluate(VF, input, integer(5), str(""))).isSameAs(input);
		assertThat(new RPad().evaluate(VF, input, integer(5), str(""))).isSameAs(input);
		// but truncation still applies
		assertThat(new LPad().evaluate(VF, str("hello"), integer(2), str(""))).isEqualTo(str("he"));
	}

	@Test
	void astralFillIsCutAtCodePointBoundaries() {
		assertThat(new LPad().evaluate(VF, str("a"), integer(4), str(SMILEY + "b")))
				.isEqualTo(str(SMILEY + "b" + SMILEY + "a"));
		assertThat(new RPad().evaluate(VF, str("a"), integer(4), str(SMILEY + "b")))
				.isEqualTo(str("a" + SMILEY + "b" + SMILEY));
		assertThat(new LPad().evaluate(VF, str("a"), integer(2), str(SMILEY))).isEqualTo(str(SMILEY + "a"));
	}

	// ---------------------------------------------------------------- repeat

	@Test
	void repeatZeroOrNegativeCountIsEmpty() {
		// pins current behaviour: a negative count yields "" (documented), not an evaluation error
		assertThat(new Repeat().evaluate(VF, str("ab"), integer(0))).isEqualTo(str(""));
		assertThat(new Repeat().evaluate(VF, str("ab"), integer(-5))).isEqualTo(str(""));
		assertThat(new Repeat().evaluate(VF, en("ab"), integer(-5))).isEqualTo(en(""));
	}

	@Test
	void repeatOfLongStringManyTimesIsBoundedByASizeGuard() {
		Literal longString = str("x".repeat(100_000));
		assertThatThrownBy(() -> new Repeat().evaluate(VF, longString, integer(1_000)))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("too large");
		// just below the guard still works
		assertThat(new Repeat().evaluate(VF, longString, integer(10)).getLabel()).hasSize(1_000_000);
	}

	@Test
	void repeatRejectsDecimalCount() {
		// pins current behaviour: the count must be an xsd:integer literal; 2.0 is an evaluation error
		assertThatThrownBy(() -> new Repeat().evaluate(VF, str("ab"), VF.createLiteral(new BigDecimal("2.0"))))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Repeat().evaluate(VF, str("ab"), VF.createLiteral(2.0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new Repeat().evaluate(VF, str("ab"), VF.createLiteral("2", CoreDatatype.XSD.LONG)))
				.isEqualTo(str("abab"));
	}

	// ---------------------------------------------------------------- reverse

	@Test
	void reversePutsCombiningMarksBeforeTheirBase() {
		// documented: reversal is by code point, so a combining mark ends up before its base character
		assertThat(new Reverse().evaluate(VF, str(DECOMPOSED_E + "x"))).isEqualTo(str("x́e"));
		assertThat(new Reverse().evaluate(VF, str("ab" + SMILEY + "cd"))).isEqualTo(str("dc" + SMILEY + "ba"));
	}

	// ---------------------------------------------------------------- left, right

	@Test
	void leftAndRightBoundaryLengths() {
		assertThat(new Left().evaluate(VF, str("abc"), integer(0))).isEqualTo(str(""));
		assertThat(new Right().evaluate(VF, str("abc"), integer(0))).isEqualTo(str(""));
		Literal whole = str("abc");
		assertThat(new Right().evaluate(VF, whole, integer(10))).isSameAs(whole);
		assertThat(new Left().evaluate(VF, whole, integer(3))).isSameAs(whole);
		// pins current behaviour: a negative n counts from the other end (PostgreSQL) instead of failing
		assertThat(new Left().evaluate(VF, str("abc"), integer(-3))).isEqualTo(str(""));
		assertThat(new Right().evaluate(VF, str("abc"), integer(-3))).isEqualTo(str(""));
		assertThat(new Left().evaluate(VF, str("abc"), integer(-4))).isEqualTo(str(""));
		assertThat(new Right().evaluate(VF, str("abc"), integer(-4))).isEqualTo(str(""));
	}

	@Test
	void leftAndRightAstralBoundaries() {
		assertThat(new Left().evaluate(VF, str(SMILEY + "a" + SMILEY), integer(2))).isEqualTo(str(SMILEY + "a"));
		assertThat(new Right().evaluate(VF, str(SMILEY + "a" + SMILEY), integer(2))).isEqualTo(str("a" + SMILEY));
		assertThat(new Left().evaluate(VF, str(SMILEY + "a" + SMILEY), integer(-1))).isEqualTo(str(SMILEY + "a"));
		assertThat(new Right().evaluate(VF, str(SMILEY + "a" + SMILEY), integer(-1))).isEqualTo(str("a" + SMILEY));
	}

	// ---------------------------------------------------------------- position, lastIndexOf

	@Test
	void emptyNeedle() {
		// pins current behaviour: an empty needle occurs at position 1 and, for lastIndexOf, at length + 1
		assertThat(new Position().evaluate(VF, str(""), str("abc")).intValue()).isEqualTo(1);
		assertThat(new Position().evaluate(VF, str(""), str("")).intValue()).isEqualTo(1);
		assertThat(new LastIndexOf().evaluate(VF, str("abc"), str("")).intValue()).isEqualTo(4);
		assertThat(new LastIndexOf().evaluate(VF, str(SMILEY + "b"), str("")).intValue()).isEqualTo(3);
		assertThat(new LastIndexOf().evaluate(VF, str(""), str("")).intValue()).isEqualTo(1);
	}

	@Test
	void needleLongerThanHaystackIsNotFound() {
		assertThat(new Position().evaluate(VF, str("abcd"), str("abc")).intValue()).isEqualTo(0);
		assertThat(new LastIndexOf().evaluate(VF, str("abc"), str("abcd")).intValue()).isEqualTo(0);
	}

	@Test
	void overlappingOccurrences() {
		assertThat(new Position().evaluate(VF, str("aa"), str("aaa")).intValue()).isEqualTo(1);
		assertThat(new LastIndexOf().evaluate(VF, str("aaa"), str("aa")).intValue()).isEqualTo(2);
		assertThat(new LastIndexOf().evaluate(VF, str("abab"), str("ab")).intValue()).isEqualTo(3);
	}

	@Test
	void positionsAreCaseSensitive() {
		assertThat(new Position().evaluate(VF, str("A"), str("abc")).intValue()).isEqualTo(0);
		assertThat(new Position().evaluate(VF, str("a"), str("Abca")).intValue()).isEqualTo(4);
		assertThat(new LastIndexOf().evaluate(VF, str("abcA"), str("a")).intValue()).isEqualTo(1);
	}

	@Test
	void positionAndLastIndexOfTakeArgumentsInOppositeOrder() {
		// position(needle, haystack) but lastIndexOf(haystack, needle); neither order raises an error
		assertThat(new Position().evaluate(VF, str("b"), str("abc")).intValue()).isEqualTo(2);
		assertThat(new Position().evaluate(VF, str("abc"), str("b")).intValue()).isEqualTo(0);
		assertThat(new LastIndexOf().evaluate(VF, str("abc"), str("b")).intValue()).isEqualTo(2);
		assertThat(new LastIndexOf().evaluate(VF, str("b"), str("abc")).intValue()).isEqualTo(0);
	}

	// ---------------------------------------------------------------- splitPart

	@Test
	void splitPartEmptyDelimiter() {
		// pins current behaviour: an empty delimiter does not split, so field 1 and -1 are the whole string and
		// every other field is empty (no evaluation error)
		assertThat(new SplitPart().evaluate(VF, str("abc"), str(""), integer(-1))).isEqualTo(str("abc"));
		assertThat(new SplitPart().evaluate(VF, str("abc"), str(""), integer(2))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("abc"), str(""), integer(-2))).isEqualTo(str(""));
	}

	@Test
	void splitPartConsecutiveLeadingAndTrailingDelimiters() {
		assertThat(new SplitPart().evaluate(VF, str("a,,b"), str(","), integer(2))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("a,,b"), str(","), integer(3))).isEqualTo(str("b"));
		assertThat(new SplitPart().evaluate(VF, str(",a"), str(","), integer(1))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str(",a"), str(","), integer(2))).isEqualTo(str("a"));
		assertThat(new SplitPart().evaluate(VF, str("a,"), str(","), integer(2))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("a,"), str(","), integer(-1))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("a,"), str(","), integer(-2))).isEqualTo(str("a"));
	}

	@Test
	void splitPartDelimiterWithRegexMetacharactersIsLiteral() {
		assertThat(new SplitPart().evaluate(VF, str("a.b.c"), str("."), integer(2))).isEqualTo(str("b"));
		assertThat(new SplitPart().evaluate(VF, str("a|b|c"), str("|"), integer(3))).isEqualTo(str("c"));
		assertThat(new SplitPart().evaluate(VF, str("a*b"), str("*"), integer(1))).isEqualTo(str("a"));
		assertThat(new SplitPart().evaluate(VF, str("abc"), str("."), integer(1))).isEqualTo(str("abc"));
	}

	@Test
	void splitPartMultiCharacterDelimiter() {
		assertThat(new SplitPart().evaluate(VF, str("a<->b<->c"), str("<->"), integer(2))).isEqualTo(str("b"));
		assertThat(new SplitPart().evaluate(VF, str("a|||b"), str("||"), integer(2))).isEqualTo(str("|b"));
		assertThat(new SplitPart().evaluate(VF, str("a" + SMILEY + SMILEY + "b"), str(SMILEY + SMILEY), integer(2)))
				.isEqualTo(str("b"));
	}

	// ---------------------------------------------------------------- split

	@Test
	void splitOfEmptyString() {
		// pins current behaviour: "" split on a delimiter is one empty part; "" split on "" is empty
		assertThat(new Split().evaluate(VF, str(""), str(",")).getLabel()).isEqualTo("[\"\"]");
		assertThat(new Split().evaluate(VF, str(""), str("")).getLabel()).isEqualTo("[]");
	}

	@Test
	void splitPreservesTrailingEmptyParts() {
		assertThat(new Split().evaluate(VF, str("a,b,,"), str(",")).getLabel()).isEqualTo("[\"a\",\"b\",\"\",\"\"]");
		assertThat(new Split().evaluate(VF, str(","), str(",")).getLabel()).isEqualTo("[\"\",\"\"]");
		assertThat("a,b,,".split(",")).containsExactly("a", "b"); // the Java behaviour split does not follow
	}

	@Test
	void splitResultIsJsonArrayWithLanguageEncoding() {
		Literal plain = new Split().evaluate(VF, str("a,b"), str(","));
		assertThat(plain.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		assertThat(plain.getLabel()).isEqualTo("[\"a\",\"b\"]");

		Literal tagged = new Split().evaluate(VF, en("a,b"), str(","));
		assertThat(tagged.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		List<?> parsed = (List<?>) JsonSupport.parse(tagged.getLabel());
		assertThat(parsed).hasSize(2).allSatisfy(element -> {
			assertThat(element).isInstanceOf(Map.class);
			Map<?, ?> object = (Map<?, ?>) element;
			assertThat(object.get("@language")).isEqualTo("en");
			assertThat(object.containsKey("@value")).isTrue();
		});
		assertThat(jsonArrayValues(tagged)).containsExactly(en("a"), en("b"));
	}

	@Test
	void splitMagicPropertyYieldsTheSameRowsAsTheScalarArray() {
		SplitTupleFunction tupleFunction = new SplitTupleFunction();
		Split scalar = new Split();
		List<Literal[]> inputs = List.of(new Literal[] { str("a,b,,c"), str(",") },
				new Literal[] { str(""), str(",") }, new Literal[] { str("abc"), str("") },
				new Literal[] { str("a" + SMILEY + "b"), str(SMILEY) }, new Literal[] { en("x;y"), str(";") },
				new Literal[] { str("a::b::"), str("::") });
		for (Literal[] input : inputs) {
			List<Value> array = jsonArrayValues(scalar.evaluate(VF, input[0], input[1]));
			List<Value> tuples = rows(tupleFunction, input[0], input[1]);
			assertThat(tuples).as(input[0] + " / " + input[1]).containsExactlyElementsOf(array);
			assertThat(tuples).hasSameSizeAs(array);
		}
	}

	// ---------------------------------------------------------------- concatWs

	@Test
	void concatWsSingleValueAndEmptySeparator() {
		assertThat(new ConcatWs().evaluate(VF, str(","), str("a"))).isEqualTo(str("a"));
		assertThat(new ConcatWs().evaluate(VF, str(""), str("a"), str("b"))).isEqualTo(str("ab"));
		assertThat(new ConcatWs().evaluate(VF, str(", "), str(""), str("b"))).isEqualTo(str(", b"));
	}

	@Test
	void concatWsUnboundValueIsAnEvaluationError() {
		// pins current behaviour: an unbound value argument is an error (as in SPARQL CONCAT), it is not skipped
		assertThatThrownBy(() -> new ConcatWs().evaluate(VF, str(","), str("a"), null, str("c")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new ConcatWs().evaluate(VF, null, str("a")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void concatWsLanguageTagRules() {
		assertThat(new ConcatWs().evaluate(VF, en(","), str("a"), str("b"))).isEqualTo(str("a,b"));
		assertThat(new ConcatWs().evaluate(VF, en(","), en("a"), en("b"))).isEqualTo(en("a,b"));
		assertThat(new ConcatWs().evaluate(VF, en(","), en("a"), str("b"))).isEqualTo(str("a,b"));
		assertThat(new ConcatWs().evaluate(VF, str(","), en("a"), VF.createLiteral("b", "de"))).isEqualTo(str("a,b"));
		assertThat(new ConcatWs().evaluate(VF, en(","), en("a"), VF.createLiteral("b", "de"))).isEqualTo(str("a,b"));
		// pins current behaviour: a language-tagged separator alone yields a plain result
		assertThat(new ConcatWs().evaluate(VF, en(","))).isEqualTo(str(""));
	}

	// ---------------------------------------------------------------- translate

	@Test
	void translateDeletesWhenToIsShorterAndIgnoresExtraToCharacters() {
		assertThat(new Translate().evaluate(VF, str("abcabc"), str("abc"), str("x"))).isEqualTo(str("xx"));
		assertThat(new Translate().evaluate(VF, str("abc"), str("a"), str("xyz"))).isEqualTo(str("xbc"));
		assertThat(new Translate().evaluate(VF, str("abc"), str("abc"), str(""))).isEqualTo(str(""));
	}

	@Test
	void translateDuplicateFromCharactersFirstMappingWins() {
		assertThat(new Translate().evaluate(VF, str("aaa"), str("aa"), str("xy"))).isEqualTo(str("xxx"));
		assertThat(new Translate().evaluate(VF, str("ab"), str("aba"), str("12"))).isEqualTo(str("12"));
	}

	@Test
	void translateMapsAstralCodePoints() {
		assertThat(new Translate().evaluate(VF, str("a" + SMILEY + "b"), str(SMILEY), str("-"))).isEqualTo(str("a-b"));
		assertThat(new Translate().evaluate(VF, str("a-b"), str("-"), str(SMILEY))).isEqualTo(str("a" + SMILEY + "b"));
		assertThat(new Translate().evaluate(VF, str("a" + SMILEY + "b"), str("a" + SMILEY), str(SMILEY + "a")))
				.isEqualTo(str(SMILEY + "ab"));
	}

	@Test
	void translateEmptyFromIsIdentity() {
		Literal input = str("abc");
		assertThat(new Translate().evaluate(VF, input, str(""), str(""))).isSameAs(input);
	}

	// ---------------------------------------------------------------- initCap

	@Test
	void initCapWordBoundaries() {
		assertThat(new InitCap().evaluate(VF, str("o-neil jean-luc"))).isEqualTo(str("O-Neil Jean-Luc"));
		assertThat(new InitCap().evaluate(VF, str("3rd 42abc"))).isEqualTo(str("3rd 42abc"));
		assertThat(new InitCap().evaluate(VF, str("a_b\tc.d(e)f"))).isEqualTo(str("A_B\tC.D(E)F"));
		assertThat(new InitCap().evaluate(VF, str("αβγ δέλτα"))).isEqualTo(str("Αβγ Δέλτα"));
		assertThat(new InitCap().evaluate(VF, str("привет мир"))).isEqualTo(str("Привет Мир"));
		Literal cjk = str("日本語 テキスト");
		assertThat(new InitCap().evaluate(VF, cjk)).isSameAs(cjk);
	}

	@Test
	void initCapLowercasesTheRestOfEachWord() {
		assertThat(new InitCap().evaluate(VF, str("HELLO WORLD"))).isEqualTo(str("Hello World"));
		assertThat(new InitCap().evaluate(VF, str("hELLO wORLD"))).isEqualTo(str("Hello World"));
		Literal already = str("Hello World");
		assertThat(new InitCap().evaluate(VF, already)).isSameAs(already);
	}

	@Test
	void initCapIsLocaleInsensitive() {
		// pins current behaviour: Character.toTitleCase / toLowerCase per code point, no locale rules
		assertThat(new InitCap().evaluate(VF, str("straße ßx"))).isEqualTo(str("Straße ßx"));
		assertThat(new InitCap().evaluate(VF, str("ıi İI"))).isEqualTo(str("Ii İi"));
		assertThat(new InitCap().evaluate(VF, str("ǆungla"))).isEqualTo(str("ǅungla"));
	}

	// ---------------------------------------------------------------- ascii, chr

	@Test
	void chrCodePointLimits() {
		assertThat(new Chr().evaluate(VF, integer(0x10FFFF))).isEqualTo(str(new String(Character.toChars(0x10FFFF))));
		assertThatThrownBy(() -> new Chr().evaluate(VF, integer(0x110000)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Chr().evaluate(VF, integer(0xD800)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Chr().evaluate(VF, integer(0xDFFF)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Chr().evaluate(VF, integer(-1))).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Chr().evaluate(VF, VF.createLiteral(Long.MIN_VALUE)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new Chr().evaluate(VF, integer(0xD7FF))).isEqualTo(str("퟿"));
		assertThat(new Chr().evaluate(VF, integer(0xE000))).isEqualTo(str(""));
	}

	@Test
	void chrOfAsciiRoundTripsToTheFirstCharacter() {
		for (String s : List.of("a", "Zebra", SMILEY + "x", "été", DECOMPOSED_E, "￿")) {
			Literal first = new Chr().evaluate(VF, new Ascii().evaluate(VF, str(s)));
			assertThat(first).as(s).isEqualTo(new Left().evaluate(VF, str(s), integer(1)));
		}
		// pins current behaviour: ascii("") is 0 and chr(0) is an error, so the round trip fails only for ""
		assertThatThrownBy(() -> new Chr().evaluate(VF, new Ascii().evaluate(VF, str(""))))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	// ---------------------------------------------------------------- normalize

	@Test
	void normalizeAllFormsAndFormNameHandling() {
		String ligature = "ﬁ"; // fi ligature
		assertThat(new Normalize().evaluate(VF, str(ligature), str("NFKD"))).isEqualTo(str("fi"));
		assertThat(new Normalize().evaluate(VF, str(ligature), str("NFC"))).isEqualTo(str(ligature));
		assertThat(new Normalize().evaluate(VF, str(ligature), str("NFD"))).isEqualTo(str(ligature));
		assertThat(new Normalize().evaluate(VF, str("é"), str("nFkD"))).isEqualTo(str(DECOMPOSED_E));
		// pins current behaviour: surrounding white space in the form name is ignored
		assertThat(new Normalize().evaluate(VF, str(DECOMPOSED_E), str(" nfc "))).isEqualTo(str("é"));
		assertThatThrownBy(() -> new Normalize().evaluate(VF, str("x"), str("NFC2")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Normalize().evaluate(VF, str("x"), str("fully-normalized")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void normalizeReturnsAlreadyNormalizedInputUnchanged() {
		Literal composed = en("é");
		assertThat(new Normalize().evaluate(VF, composed)).isSameAs(composed);
		assertThat(new Normalize().evaluate(VF, composed, str("NFC"))).isSameAs(composed);
		Literal decomposed = str(DECOMPOSED_E);
		assertThat(new Normalize().evaluate(VF, decomposed, str("NFD"))).isSameAs(decomposed);
	}

	@Test
	void normalizeUnicodeAliasBehavesLikeNormalize() {
		Normalize normalize = new Normalize();
		NormalizeUnicode alias = new NormalizeUnicode();
		for (String form : List.of("NFC", "NFD", "NFKC", "NFKD", "")) {
			for (Literal input : List.of(str(DECOMPOSED_E), en("é"), str("ﬁ"), str(""))) {
				assertThat(alias.evaluate(VF, input, str(form))).as(form + " " + input)
						.isEqualTo(normalize.evaluate(VF, input, str(form)));
			}
		}
		assertThat(alias.evaluate(VF, str(DECOMPOSED_E))).isEqualTo(normalize.evaluate(VF, str(DECOMPOSED_E)));
		assertThatThrownBy(() -> alias.evaluate(VF, str("x"), str("NFX")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}
}
